mapper.select:
select exe.bokset_id as booksetId, /*账套代码*/ bok.bookset_name as booksetName, /*账套名称*/ exe.finprod_id as finprodId, /*金融产品代码*/ fp.finprod_name as finprodName, /*金融产品全称*/ exe.branch as branch, /* 分支序号 */ exe.exe_date_type as exeDateType /*含权债摊销日*/ from BOK_FIN_PRODUCT_VALUATION_PARA exe left join BOK_BOOKSET bok on exe.bokset_id = bok.bookset_id left join FIN_PRODUCT fp on exe.finprod_id = fp.finprod_id and fp.finprod_type = 'F01'
AND exe.bokset_id in
#{item}
AND exe.finprod_Id in
#{item}

mapper.delete:
	    delete from BOK_FIN_PRODUCT_VALUATION_PARA
        where BOKSET_ID = #{booksetId,jdbcType=VARCHAR} 
            and FINPROD_ID = #{finprodId,jdbcType=VARCHAR} 
            and BRANCH = #{branch,jdbcType=DECIMAL}

mapper.select:
select fp.finprod_id as id, /*金融产品代码*/ fp.finprod_name as text /*金融产品全称*/ from FIN_PRODUCT fp where fp.finprod_type = 'F01' and fp.is_right = 'Y'
AND ( fp.finprod_id LIKE CONCAT('%', CONCAT(#{search}, '%')) OR fp.finprod_name LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND fp.finprod_id = #{initValue}
